import{_ as o,c as t,o as a,ae as r}from"./chunks/framework.CXzlQjHd.js";const h=JSON.parse('{"title":"Code of conduct","description":"","frontmatter":{},"headers":[],"relativePath":"Code-of-Conduct.md","filePath":"Code-of-Conduct.md"}'),i={name:"Code-of-Conduct.md"};function n(s,e,l,c,p,d){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="code-of-conduct" tabindex="-1">Code of conduct <a class="header-anchor" href="#code-of-conduct" aria-label="Permalink to &quot;Code of conduct&quot;">​</a></h1><p>(The latest version can be found at <a href="https://www.hotosm.org/code-of-conduct" target="_blank" rel="noreferrer">https://www.hotosm.org/code-of-conduct</a>)</p><p>Welcome to Humanitarian OpenStreetMap Team. HOT is committed to providing a welcoming and safe environment for people of all races, gender identities, gender expressions, sexual orientations, physical abilities, physical appearances, socio-economic backgrounds, nationalities, ages, religions, and beliefs.</p><p>The HOT community principles are:</p><ul><li><p><strong>Be friendly and patient.</strong> Be generous and kind in both giving and accepting critique. Critique is a natural and important part of our culture. Good critiques are kind, respectful, clear, and constructive, focused on goals and requirements rather than personal preferences. You are expected to give and receive criticism with grace. Be considerate in speech and actions, and actively seek to acknowledge and respect the boundaries of fellow attendees.</p></li><li><p><strong>Be welcoming.</strong> We strive to be a community that welcomes and supports people of all backgrounds and identities. Some examples of behavior that contributes to creating a positive environment include:</p><ul><li><p>Using welcoming and inclusive language.</p></li><li><p>Being respectful of differing viewpoints and experiences.</p></li><li><p>Gracefully accepting constructive criticism.</p></li><li><p>Showing empathy towards other community members.</p></li><li><p>Placing collective interest before your own interest.</p></li></ul></li><li><p><strong>Be considerate.</strong> Your work will be used by other people, and you in turn will depend on the work of others. Any decision you take will affect users and colleagues, and you should take those consequences into account when making decisions. Remember that we&#39;re a world-wide community, so you might not be communicating in someone else&#39;s primary language.</p></li><li><p><strong>Be respectful.</strong> Not all of us will agree all the time, but disagreement is no excuse for poor behavior and poor manners. We might all experience some frustration now and then, but we cannot allow that frustration to turn into a personal attack. It’s important to remember that a community where people feel uncomfortable or threatened is not a productive one. Members of the HOT community should be respectful when dealing with other members as well as with people outside the HOT community.</p></li><li><p><strong>Be careful in your word choice.</strong> We are a global community of professionals, and we conduct ourselves professionally. Be kind to others. Do not insult or put down other participants. Harassment and other exclusionary behavior aren&#39;t acceptable. This includes, but is not limited to:</p><ul><li><p>Violent threats or language directed against another person.</p></li><li><p>Discriminatory jokes and language.</p></li><li><p>Posting sexually explicit or violent material.</p></li><li><p>Posting (or threatening to post) other people&#39;s personally identifying information (&quot;doxing&quot;).</p></li><li><p>Personal insults, especially those using racist or sexist terms.</p></li><li><p>Unwelcome sexual attention.</p></li><li><p>Advocating for, or encouraging, any of the above behavior.</p></li><li><p>Repeated harassment of others. In general, if someone asks you to stop, then stop.</p></li></ul></li><li><p><strong>Assume all communications are positive.</strong> Always remain polite, and assume good faith. It is surprisingly easy to misunderstand each other, be it online or in person, particularly in such a culturally diverse setting as ours. Misunderstandings are particularly easy to arise when we are in a rush, or otherwise distracted. Please ask clarifying questions before assuming that a communication was inappropriate.</p></li><li><p><strong>When we disagree, try to understand why.</strong> Disagreements, both social and technical, happen easily and often. It is important that we resolve such disagreements and differing views constructively. At times it can be hard to appreciate a viewpoint that contradicts your own perceptions. Instead of pushing back, try to understand where the other person is coming from, and don’t be afraid to ask questions. You can be most helpful if your own replies serve to clarify, rather than to escalate an issue. Also don’t forget that it can be easy to make mistakes, and allow for the possibility that the mistake may have been yours. When this happens it is better to resolve the issue together, and to learn from the experience together, than to place blame.</p></li></ul><p>Original text courtesy of the <a href="http://web.archive.org/web/20141109123859/http://speakup.io/coc.html" target="_blank" rel="noreferrer">Speak Up! project</a>.</p><p>Further sources:</p><ul><li><p><a href="https://adainitiative.org/2014/02/18/howto-design-a-code-of-conduct-for-your-community/" target="_blank" rel="noreferrer">Ada Initiative: HOWTO design a code of conduct for your community</a></p></li><li><p><a href="https://github.com/drtortoise/critical-algorithm-studies/blob/master/code-of-conduct.md" target="_blank" rel="noreferrer">Algorithm Club Code of Conduct</a></p></li><li><p><a href="https://github.com/AmericanRedCross/team-code-of-conduct" target="_blank" rel="noreferrer">American Red Cross GIS Team Code of Conduct</a></p></li><li><p><a href="http://contributor-covenant.org/" target="_blank" rel="noreferrer">Contributor Covenant – A Code of Conduct for Open Source Projects</a></p></li><li><p><a href="https://www.djangoproject.com/conduct/" target="_blank" rel="noreferrer">Django Code of Conduct</a></p></li><li><p><a href="https://www.mozilla.org/en-US/about/governance/policies/participation/" target="_blank" rel="noreferrer">Mozilla Community Participation Guidelines</a></p></li><li><p><a href="http://code-of-conduct.voxmedia.com/" target="_blank" rel="noreferrer">Vox Media Code of Conduct</a></p></li></ul><h2 id="complaint-handling-process" tabindex="-1">Complaint Handling Process <a class="header-anchor" href="#complaint-handling-process" aria-label="Permalink to &quot;Complaint Handling Process&quot;">​</a></h2><p>As a first measure, it is preferable to work out issues directly with the people involved, or to work with other Community Members who can help you resolve the issue. This may take several forms:</p><ul><li><p>Talk with one another. Assume that communications are positive and that people are treating each other with respect. Cues about emotions are often lacking from digital communications. Many of our modes of digital communication tend towards brevity, which can be easier to interpret incorrectly as being negative.</p></li><li><p>Contact a representative of the <a href="https://www.hotosm.org/community/working-groups/" target="_blank" rel="noreferrer">Community Working Group</a>, which exists to support the HOT Community. Representatives are available to discuss any concerns about behaviour within the community, or ideas to promote positive behaviours. You can email them at <a href="mailto:community@hotosm.org" target="_blank" rel="noreferrer">community@hotosm.org</a>.</p></li><li><p>Contact a representative of the <a href="https://www.hotosm.org/community/working-groups/" target="_blank" rel="noreferrer">Governance Working Group</a>, which drafted these recommendations and the CoC. Representatives are available to provide advice on particular scenarios, as well as on the processes around the CoC.</p></li><li><p>Contact the HOT Chair of Voting Members.</p></li><li><p>Contact a <a href="https://www.hotosm.org/board" target="_blank" rel="noreferrer">HOT Board Member</a>. Board members are well versed in the community and its management. They can offer advice on your particular situation, and know the resources of the organization that may be available to you.</p></li><li><p>Contact the HOT Community Partnerships Manager.</p></li></ul><p>When these informal processes fail, or when a situation warrants an immediate response by HOT, you can evoke the <strong>HOT Policy and Code of Conduct Complaint Handling Process</strong>. This process was adopted by HOT Voting Members in 2016 to provide a more formal means of enforcement for our community standards. You start it by emailing <a href="mailto:compaints@hotosm.org" target="_blank" rel="noreferrer">complaints@hotosm.org</a> with a description of your complaint, your name, and the name of the offending party. All complaints will be considered confidential. The full process is described <a href="https://docs.google.com/document/d/1xb-SPADtSbgwl6mAgglHMPHpknt-E7lKRoIcSbW431A/edit" target="_blank" rel="noreferrer">here</a></p>',12)]))}const m=o(i,[["render",n]]);export{h as __pageData,m as default};
